using System.Security.Cryptography.X509Certificates;

namespace ModsDude.Server.Api.Accounts;

/// <summary>
/// The certificates tokens are signed and encrypted with, as base64 PFX files with their passwords.
/// Generated by scripts/new-token-certificates.ps1 and supplied through the environment.
/// </summary>
public sealed record TokenCertificatesOptions
{
    public const string SectionName = "TokenCertificates";


    public string SigningCertificate { get; init; } = "";
    public string SigningCertificatePassword { get; init; } = "";
    public string EncryptionCertificate { get; init; } = "";
    public string EncryptionCertificatePassword { get; init; } = "";


    public bool IsConfigured
        => SigningCertificate.Length > 0 && EncryptionCertificate.Length > 0;


    public X509Certificate2 LoadSigningCertificate()
        => Load(SigningCertificate, SigningCertificatePassword);

    public X509Certificate2 LoadEncryptionCertificate()
        => Load(EncryptionCertificate, EncryptionCertificatePassword);


    private static X509Certificate2 Load(string base64, string password)
        => X509CertificateLoader.LoadPkcs12(Convert.FromBase64String(base64), password, X509KeyStorageFlags.EphemeralKeySet);
}
